<style>
.performance-hub{--hub-accent:#a5b4fc;--hub-surface:#151722;--hub-line:#ffffff16;--hub-muted:#a9adbe;font-size:.9rem}
.performance-hub .panel{background:linear-gradient(135deg,#1b1d2b8c,#10121c80);border:1px solid var(--hub-line);border-radius:16px;padding:1.5rem;margin-top:1.25rem;box-shadow:0 8px 28px #0000000d}
.performance-hub .hub-hero{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:2rem;align-items:center;padding:2rem!important;border:1px solid #a5b4fc30!important;background:radial-gradient(ellipse at right,#6366f11c,transparent 65%),#151722!important;border-left:1px solid #a5b4fc30!important}
.performance-hub .hub-hero h2{font-size:clamp(1.7rem,2.5vw,2.5rem);line-height:1.15;letter-spacing:-.035em;font-weight:650}.performance-hub .hub-hero p{line-height:1.7}.performance-hub .hub-hero .hub-period{font-size:.75rem;color:#c7d2fe}.performance-hub .hub-score{border-left:1px solid #a5b4fc30;padding-left:2rem;min-width:150px}.performance-hub .hub-score strong{font-size:2.6rem;line-height:1.1;font-weight:600;color:#e0e7ff}.performance-hub .hub-score span{display:block;font-size:.75rem;color:var(--hub-muted);margin-top:.4rem}
.performance-hub .overview-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;border:1px solid var(--hub-line);border-radius:14px;overflow:hidden}.performance-hub .overview-cards .panel{border:0;border-right:1px solid var(--hub-line);border-radius:0;box-shadow:none;background:#151722}.performance-hub .overview-cards .panel:last-child{border-right:0}.performance-hub .overview-cards .panel p:last-child{font-size:1.7rem;line-height:1.2;font-weight:600;overflow-wrap:anywhere}
.performance-hub nav[aria-label="Performance views"]{gap:.35rem;flex-wrap:nowrap;overflow-x:auto;padding:.6rem;background:#10121b;border:1px solid var(--hub-line);border-radius:12px;scrollbar-width:thin;scrollbar-color:#a5b4fc55 transparent}.performance-hub nav[aria-label="Performance views"] a{flex-shrink:0;white-space:nowrap;border:0;border-radius:8px;padding:.75rem 1rem;font-size:.78rem;transition:background .15s}.performance-hub nav[aria-label="Performance views"] a[aria-current="page"]{background:#a5b4fc20;color:#e0e7ff;box-shadow:inset 0 0 0 1px #a5b4fc35}.performance-hub nav[aria-label="Performance views"] a:hover{background:#ffffff08}
.performance-hub h2,.performance-hub h3{letter-spacing:-.015em}.performance-hub .muted{color:var(--hub-muted);font-size:.78rem;line-height:1.7}.performance-hub .scroll{border:1px solid var(--hub-line);border-radius:10px;scrollbar-width:thin;scrollbar-color:#a5b4fc55 transparent}.performance-hub table{border-collapse:separate;border-spacing:0;font-size:.78rem}.performance-hub th{background:#222536;color:#c7d2fe;padding:1rem;font-size:.75rem;font-weight:600;letter-spacing:0;line-height:1.5;white-space:normal}.performance-hub td{padding:1rem;line-height:1.65;border-bottom:1px solid #ffffff0c}.performance-hub tbody tr:nth-child(even){background:#ffffff03}.performance-hub tbody tr:hover{background:#a5b4fc08}.performance-hub td .tag{white-space:nowrap;overflow-wrap:normal;word-break:keep-all}.performance-hub .tag{border:1px solid #ffffff20;border-radius:7px;padding:.35rem .65rem;font-size:.72rem;line-height:1.5}.performance-hub .actions{align-items:center;gap:.6rem}.performance-hub .primary,.performance-hub button[type=submit]{border-radius:8px;padding:.75rem 1rem;font-size:.8rem;line-height:1.4;box-shadow:0 2px 8px #00000015}
.performance-hub input:not([type=checkbox]):not([type=radio]):not([type=hidden]),.performance-hub select,.performance-hub textarea{border:1px solid #ffffff20;border-radius:8px;padding:.7rem .8rem;background:#10121b;color:#f4f4f5;min-width:0;max-width:100%;font-size:.8rem}.performance-hub input:focus,.performance-hub select:focus,.performance-hub textarea:focus{outline:2px solid #a5b4fc70;outline-offset:1px}.performance-hub summary{line-height:1.6}.performance-hub details.panel>summary{color:#dce1f8;font-size:.9rem}.performance-hub summary::marker{color:#a5b4fc}.performance-hub a:focus-visible,.performance-hub button:focus-visible,.performance-hub summary:focus-visible{outline:2px solid #a5b4fc;outline-offset:4px}.performance-hub meter{accent-color:#a5b4fc;height:12px}
[data-theme=light] .performance-hub{--hub-muted:#5b6478;--hub-line:#dce1ea}[data-theme=light] .performance-hub .panel,[data-theme=light] .performance-hub .hub-hero,[data-theme=light] .performance-hub .overview-cards .panel{background:#fff!important}[data-theme=light] .performance-hub th{background:#eef1fb;color:#373d67}[data-theme=light] .performance-hub td{border-color:#e5e7eb}[data-theme=light] .performance-hub input:not([type=checkbox]):not([type=radio]):not([type=hidden]),[data-theme=light] .performance-hub select,[data-theme=light] .performance-hub textarea{background:#fff;color:#17243b;border-color:#cbd5e1}[data-theme=light] .performance-hub nav[aria-label="Performance views"]{background:#f5f7fc}[data-theme=light] .performance-hub nav[aria-label="Performance views"] a[aria-current=page]{color:#373d67;background:#e3e8fa}[data-theme=light] .performance-hub .hub-score strong,[data-theme=light] .performance-hub .hub-period,[data-theme=light] .performance-hub details.panel>summary{color:#373d67}
@media(max-width:1100px){.performance-hub .overview-cards{grid-template-columns:repeat(3,minmax(0,1fr))}.performance-hub .overview-cards .panel{border-bottom:1px solid var(--hub-line)}}@media(max-width:640px){.performance-hub .panel{padding:1rem}.performance-hub .hub-hero{grid-template-columns:1fr;gap:1.2rem;padding:1.25rem!important}.performance-hub .hub-score{border-left:0;border-top:1px solid #a5b4fc30;padding:1rem 0 0}.performance-hub .hub-score strong{font-size:2rem}.performance-hub .overview-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.performance-hub th,.performance-hub td{padding:.8rem}.performance-hub .actions{gap:.5rem}}
</style>
